      try {
        if (new.target) {
          result = Reflect.construct(state.impl, args, new.target)
        } else {
          result = state.impl.apply(this, args)
        }
        type = 'ok'
      } catch (err: any) {
        result = err
        type = 'error'
        state.results.push([type, err])
        throw err
